/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, AppliedUndef, E, Float, Mul, Pow, Rational, Relational, Sym, add, combsimp, fn, gammasimp, mul, pi, piecewise, pow, powsimp, simplify, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.simplify.combsimp", () => {
  it("combsimp(factorial(n)/factorial(n - 3))", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(combsimp(mul(pow(fn('factorial', [add(Rational.of(-3n, 1n, { gcd: 1n }), n)]), Rational.of(-1n, 1n, { gcd: 1n })), fn('factorial', [n]))))).toBe('n*(n - 2)*(n - 1)');
  });
  it("combsimp(binomial(n+1, k+1)/binomial(n, k))", () => {
    const n = new Sym('n', { integer: true });
    const k = new Sym('k', { integer: true });
    expect(sympyStr(combsimp(mul(pow(fn('binomial', [n, k]), Rational.of(-1n, 1n, { gcd: 1n })), fn('binomial', [add(Rational.of(1n, 1n, { gcd: 1n }), n), add(Rational.of(1n, 1n, { gcd: 1n }), k)]))))).toBe('(n + 1)/(k + 1)');
  });
});

describe("doctests of sympy.simplify.gammasimp", () => {
  it("gammasimp(gamma(x)/gamma(x - 3))", () => {
    const x = new Sym('x');
    expect(sympyStr(gammasimp(mul(pow(fn('gamma', [add(Rational.of(-3n, 1n, { gcd: 1n }), x)]), Rational.of(-1n, 1n, { gcd: 1n })), fn('gamma', [x]))))).toBe('(x - 3)*(x - 2)*(x - 1)');
  });
  it("gammasimp(gamma(n + 3))", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(gammasimp(fn('gamma', [add(Rational.of(3n, 1n, { gcd: 1n }), n)])))).toBe('gamma(n + 3)');
  });
});

